// Advances the quest tick counter and fires/reschedules/frees expired quest timers in pQuestControl->pTimer.
// @sourcefile .\QUESTS\QUESTS.CPP
void __fastcall QUEST_ProcessQuestTimers(::SGAMEDATA * pGame) {
    uint8_t bTimerDone;
    BOOL bIsBadPtr;
    D2QuestTimerStrc* pTimer;
    D2QuestControlStrc* pQuestControl = pGame->pQuestControl;
    if (!pQuestControl) {
      return;
    }

    pQuestControl->nTickcount++;
    if (pQuestControl->nTickcount == -1) {
      for (pTimer = pQuestControl->pTimer; pTimer; pTimer = pTimer->pNext) {
        pTimer->dwTicks = -1 - pTimer->dwTicks;
      }
    }

    pQuestControl->bExecuting = 1;
    pTimer = pQuestControl->pTimer;
    D2QuestTimerStrc* pMemoryToFree = 0;
    while (true) {
      D2QuestTimerStrc* pPrevTimer;
      pPrevTimer = pMemoryToFree;
      pMemoryToFree = pTimer;
      if (!pMemoryToFree) {
        break;
      }

      pTimer = pMemoryToFree->pNext;
      if ((uint32_t)pMemoryToFree->dwTicks < (uint32_t)pQuestControl->nTickcount) {
        /* FARPROC lpfn for IsBadCodePtr */ bIsBadPtr = IsBadCodePtr((FARPROC)pMemoryToFree->pfUpdate);
        if (bIsBadPtr) {
          Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x3f0);
          exit(-1);
        }

        bTimerDone = pMemoryToFree->pfUpdate(pGame, pMemoryToFree->pQuest);
        if (bTimerDone == '\x01') {
          if (!pPrevTimer) {
            pQuestControl->pTimer = pMemoryToFree->pNext;
            D2_FREE_POOL_AT(pGame->pMemoryPool, pMemoryToFree, ".\\QUESTS\\QUESTS.CPP", 0x3f7);
            pMemoryToFree = 0;
          } else {
            pPrevTimer->pNext = pMemoryToFree->pNext;
            D2_FREE_POOL_AT(pGame->pMemoryPool, pMemoryToFree, ".\\QUESTS\\QUESTS.CPP", 0x3fe);
            pMemoryToFree = pPrevTimer;
          }
        } else {
          pMemoryToFree->dwTicks = pMemoryToFree->dwTimeout + pQuestControl->nTickcount;
        }
      }
    }

    pQuestControl->bExecuting = 0;
}

// @sourcefile .\QUESTS\QUESTS.CPP
void __fastcall AddQuestTimer(D2QuestDataStrc * pQuestData, QUESTUPDATE fpQuestUpdate, int32_t nTimeout) {
    D2QuestControlStrc* pQuestControl = pQuestData->pGame->pQuestControl;
    if (!pQuestControl) {
      return;
    }
    if (pQuestControl->bExecuting) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x417);
      exit(-1);
    }

    D2QuestTimerStrc* pExistingTimer = pQuestControl->pTimer;
    D2QuestTimerStrc* pNewTimer = D2_NEW_POOL_AT(pQuestData->pGame->pMemoryPool, D2QuestTimerStrc, ".\\QUESTS\\QUESTS.CPP", 0x41a);
    pNewTimer->pNext = pExistingTimer;
    pNewTimer->pfUpdate = fpQuestUpdate;
    pNewTimer->pQuest = pQuestData;
    pNewTimer->dwTicks = pQuestControl->nTickcount + nTimeout;
    pNewTimer->dwTimeout = nTimeout;
    pQuestControl->pTimer = pNewTimer;
}

// Determines the display byte to write into the quest-log packet for a single quest. Reads QUESTSTATE_JustCompleted and QUESTSTATE_CannotCompleteQuestInGame from the bit buffer, applies special-case logic for TheSearchForCain (Cain rescued check) and TheTaintedSun, and writes the resulting state byte into pQuestData2->nQuestNoInternal for the caller to pack into the log packet.
void __fastcall QUEST_GetQuestLogDisplayState(D2QuestDataStrc * pQuestData, uint8_t * pQuestData2, D2BitBufferStrc * pBitBuffer) {
    bool bCainRescued;
    BOOL bCannotComplete = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_CannotCompleteQuestInGame);
    if (!(pQuestData->nStateFlag < pQuestData->nInitNo)) {
      BOOL bJustCompleted;
      bJustCompleted = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_JustCompleted);
      if (bJustCompleted == 1) {
        if ((int)pQuestData->nQuestIdReal >= 0x29) {
          Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x455);
          exit(-1);
        }

        *pQuestData2 = pQuestData->nStateFlagPrev;
        return;
      }
      if (pQuestData->nQuestNoInternal != QUESTINT_TheSearchForCain || !bCannotComplete) {
        if (pQuestData->nQuestNoInternal == QUESTINT_TheTaintedSun) {
          *pQuestData2 = (pQuestData->nStateFlagPrev != 4) * '\b' + 4;
          return;
        }

        *pQuestData2 = 0xc;
        return;
      }

      bCainRescued = pQuestData->nStateFlag == 6;
    } else {
      if (bCannotComplete) {
        *pQuestData2 = 0xc;
        return;
      }
      if (pQuestData->nQuestNoInternal != QUESTINT_TheSearchForCain || pQuestData->nStateFlagPrev != 6) {
        *pQuestData2 = pQuestData->nStateFlagPrev;
        return;
      }

      bCannotComplete = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_JustCompleted);
      bCainRescued = !bCannotComplete;
    }
    if (!bCainRescued) {
      *pQuestData2 = pQuestData->nStateFlagPrev;
      return;
    }

    *pQuestData2 = 0xc;
}

