// Builds and sends packet 0x91 (NpcGossip) to the player's client for a given act, listing which intro NPCs the player has already spoken with. Selects the act-specific NPC list (Acts I/II/III/V), calls INTRONPC_FillInPacketWithIntroNpcIds to populate the packet, and sends it only if at least one NPC entry needs to be communicated.
// @sourcefile .\QUESTS\QUESTS.CPP
BOOL __fastcall INTRONPC_FillInPacketWithIntroNpcIdsInAct(::SGAMEDATA * pGame, D2UnitStrc * pUnit, eAct nActNo) {
    bool bNeedSend;
    D2UnitDataPlayerInteractedNPCStrc* pInteractedNPCsAfterSend;
    int* aNpcList;
    D2GSPacketSrv0x91 pD2GSPacketSrv0x91;
    int32_t nListSize;
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pUnit);
    D2UnitDataPlayerInteractedNPCStrc* pInteractedNPCs = pPlayerData->pInteractedNPCs[pGame->nDifficulty];
    switch (nActNo) {
      case ACT_I:
        nListSize = 6;
      aNpcList = NPCINTRO_ListAct1;
      break;
      case ACT_II:
        nListSize = 11;
      aNpcList = NPCINTRO_ListAct2;
      break;
      case ACT_III:
        nListSize = 7;
      aNpcList = NPCINTRO_ListAct3;
      break;
      default:
        {
          return (BOOL)(uintptr_t)pInteractedNPCs;
        }
      case ACT_V:
        nListSize = 7;
      aNpcList = NPCINTRO_ListAct5;
    }

    BOOL bNeedToBeSent = INTRONPC_FillInPacketWithIntroNpcIds(pInteractedNPCs, aNpcList, nListSize, &pD2GSPacketSrv0x91);
    pInteractedNPCs = 0;
    if (bNeedToBeSent) {
      D2ClientStrc* pClient;
      pD2GSPacketSrv0x91.nPacketId = 0x91;
      pD2GSPacketSrv0x91.nAct = nActNo;
      pClient = UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\QUESTS\\QUESTS.CPP", 0xab7);
      GAME::SCmd::NET_D2GS_SERVER_Send_0x91_WELCOME_BACK(pClient, &pD2GSPacketSrv0x91);
      pInteractedNPCs = pInteractedNPCsAfterSend;
    }

    return (BOOL)(uintptr_t)pInteractedNPCs;
}

void __fastcall QUESTGUID_AddPlayerToList(D2QuestGUIDStrc * pQuestGUID, int32_t nPlayerGUID) {
    uint16_t nPlayerCount = pQuestGUID->nPlayerCount;
    if (nPlayerCount >= 0x20) {
      return;
    }
    if (nPlayerCount) {
      int nSearchIdx = 0;
      do {
        if (pQuestGUID->aPlayerGUID[nSearchIdx] == nPlayerGUID) {
          return;
        }

        nSearchIdx++;
      } while (nSearchIdx < (int)(uint32_t)pQuestGUID->nPlayerCount);
    }

    pQuestGUID->aPlayerGUID[nPlayerCount] = nPlayerGUID;
    pQuestGUID->nPlayerCount++;
}

uint32_t __fastcall QUESTGUID_RemovePlayerFromList(D2QuestGUIDStrc * pQuestGUID, int32_t nPlayerGUID) {
    uint32_t nPlayerCount = (uint32_t)pQuestGUID->nPlayerCount;
    int nSearchIdx = 0;
    if (!nPlayerCount) {
      return 0;
    }

    do {
      if (pQuestGUID->aPlayerGUID[nSearchIdx] == nPlayerGUID) {
        if (nSearchIdx != nPlayerCount - 1) {
          pQuestGUID->aPlayerGUID[nSearchIdx] = pQuestGUID->aPlayerGUID[nPlayerCount - 1];
        }

        pQuestGUID->nPlayerCount--;
        return 1;
      }

      nSearchIdx++;
    } while (nSearchIdx < (int)(uint32_t)pQuestGUID->nPlayerCount);

    return 0;
}

// Returns 1 if iValue is one of the first nPlayerCount entries of
// pQuestGUID->aPlayerGUID, else 0. ECX is a D2QuestGUIDStrc (int[32] at +0, word count at +0x80);
// every caller passes a quest data block's sQuestGUID member.
BOOL __fastcall QUESTGUID_SearchForValueInIntArray32(D2QuestGUIDStrc * pQuestGUID, int32_t iValue) {
    int nSearchIdx = 0;
    if (!pQuestGUID->nPlayerCount) {
      return 0;
    }

    do {
      /* If the value is found, stop and return 1 */ if (pQuestGUID->aPlayerGUID[nSearchIdx] == iValue) {
        return 1;
      }

      nSearchIdx++;
    } while (nSearchIdx < (int)(uint32_t)pQuestGUID->nPlayerCount);

    return 0;
}

BOOL __fastcall QUEST_HasPlayerParticipated(D2QuestDataStrc * pQuestData, int32_t nPlayerGUID) {
    uint32_t nPlayerCount = (uint32_t)pQuestData->sQuestGUID.nPlayerCount;
    int nSearchIdx = 0;
    if (!nPlayerCount) {
      return 0;
    }

    int* pGuidIter = pQuestData->sQuestGUID.aPlayerGUID;
    do {
      if (*pGuidIter == nPlayerGUID) {
        return 1;
      }

      nSearchIdx++;
      pGuidIter++;
    } while (nSearchIdx < (int)nPlayerCount);

    return 0;
}

void __fastcall QUESTGUID_SetPlayerCountToZero(D2QuestGUIDStrc * pQuestGUID) {
    pQuestGUID->nPlayerCount = 0;
}

// @wasnamed QUESTGUID_RemovePlayerFromList - one name on two different functions.
// @evidence Takes D2QuestDataStrc + D2QuestArgStrc, resolves the player
// GUID (-1 if none) and delegates to 00545240. A wrapper, not the list operation itself.
void __fastcall QUESTGUID_RemovePlayerFromQuest(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    if (pQuestData->sQuestGUID.nPlayerCount <= 0) {
      return;
    }
    if (!pQuestArgs->pPlayer) {
      QUESTGUID_RemovePlayerFromList(&pQuestData->sQuestGUID, -1);
      return;
    }

    QUESTGUID_RemovePlayerFromList(&pQuestData->sQuestGUID, pQuestArgs->pPlayer->nUnitGUID);
}

// Searches outward from a candidate POINT in expanding rings (up to nSearchIterations passes, stride 2) for a map tile that passes a collision-vector check (eCollisionFlags) within nScanRadius. Steps across nearby rooms via DRLGROOM_FindBetterNearbyRoom when the search position leaves the current room. On success writes the adjusted tile coordinates back into pPoint and the containing room into *pRoomsNear; on failure sets *pRoomsNear to NULL.
void __fastcall FindSpawnableLocation(D2RoomStrc * pRoom, POINT * pPoint, uint32_t nScanRadius, int32_t neCollisionFlags, D2RoomStrc * * pRoomsNear, int32_t nMaxTries, int32_t nSearchIterations) {
    eCollisionFlags wCollisionResult;
    D2RoomStrc* pCandidateRoom;
    int nYStep;
    uint32_t nRoomYStart;
    uint32_t nX;
    uint32_t nY;
    D2DrlgRoomCoordsStrc sRoomCoords;
    int nYInner;
    int nXStep;
    int nNegRadius;
    D2RoomStrc* pRowRoom;
    uint32_t nHalfRadius = nScanRadius >> 1;
    uint32_t nCurX = pPoint->x - nHalfRadius;
    int nScanOriginY = pPoint->y - nHalfRadius;
    uint32_t nScanOriginX = nCurX;
    POINT* pOutPoint = pPoint;
    D2RoomStrc* pOrigRoom = pRoom;
    D2Common::DUNGEON::Dungeon::DRLGROOM_GetRoomCoordinates(pRoom, &sRoomCoords);
    int nRadius = 1;
    if (1 < nSearchIterations) {
      uint32_t nVectorX;
      nNegRadius = -1;
      nRoomYStart = sRoomCoords.dwYStart;
      do {
        nYStep = nNegRadius;
        nYInner = nRadius;
        if (nRadius > nNegRadius) {
          do {
            nY = nYInner + nScanOriginY;
            pRowRoom = pRoom;
            if ((int)nY < (int)nRoomYStart || (int)nY >= (int)(sRoomCoords.dwYSize + nRoomYStart)) {
              pRowRoom = D2Client::UNIT::Player::DRLGROOM_FindBetterNearbyRoom(pRoom, nCurX, nY);
              nYStep = nNegRadius;
              nRoomYStart = sRoomCoords.dwYStart;
            }
            if (pRowRoom) {
              nXStep = nYStep;
              if (nYStep < nRadius) {
                nX = nYStep + nScanOriginX;
                do {
                  pCandidateRoom = pRowRoom;
                  D2Common::DUNGEON::Dungeon::DRLGROOM_GetRoomCoordinates(pRowRoom, &sRoomCoords);
                  nCurX = nX;
                  if ((int)nX < sRoomCoords.dwXStart || (int)nY >= sRoomCoords.dwXSize + sRoomCoords.dwXStart) {
                    pCandidateRoom = D2Client::UNIT::Player::DRLGROOM_FindBetterNearbyRoom(pRowRoom, nX, nY);
                  }
                  if (pCandidateRoom) {
                    nVectorX = nScanRadius * 2 + 1;
                    wCollisionResult = D2Common::Collision::CheckCollision_Vector(pCandidateRoom, nX, nY, nVectorX, nVectorX, neCollisionFlags);
                    if (wCollisionResult == COLBIT_NONE && nX >= (uint32_t)sRoomCoords.dwXStart && nX < (uint32_t)(sRoomCoords.dwXSize + sRoomCoords.dwXStart) && nY >= (uint32_t)sRoomCoords.dwYStart && nY < (uint32_t)(sRoomCoords.dwYSize + sRoomCoords.dwYStart)) {
                      pOutPoint->x = nX + nHalfRadius;
                      pOutPoint->y = nY + nHalfRadius;
                      pCandidateRoom = D2Client::UNIT::Player::DRLGROOM_FindBetterNearbyRoom(pOrigRoom, nX + nHalfRadius, nY + nHalfRadius);
                      *pRoomsNear = pCandidateRoom;
                      return;
                    }
                  }

                  nXStep += 2;
                  nX += 2;
                  nYStep = nNegRadius;
                  nRoomYStart = sRoomCoords.dwYStart;
                  pRoom = pOrigRoom;
                } while (nXStep < nRadius);
              }
            }

            nYInner += -2;
          } while (nYInner > nYStep);
        }

        nRadius++;
        nNegRadius = nYStep - 1;
      } while (nRadius < nSearchIterations);
    }

    *pRoomsNear = 0;
}

void __fastcall SetRewardAndFinishFlags(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    ::SGAMEDATA* pGame = pQuestData->pGame;
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pQuestArgs->pPlayer);
    D2BitBufferStrc* pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
    BOOL bRewardAwaits = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_RewardAwaits);
    if (bRewardAwaits != 1) {
      return;
    }

    bRewardAwaits = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Completed);
    if (!(bRewardAwaits && pQuestData->sQuestGUID.nPlayerCount > 0)) {
      return;
    }
    if (!pQuestArgs->pPlayer) {
      QUESTGUID_RemovePlayerFromList(&pQuestData->sQuestGUID, -1);
      return;
    }

    QUESTGUID_RemovePlayerFromList(&pQuestData->sQuestGUID, pQuestArgs->pPlayer->nUnitGUID);
}

// Sends quest state information to a specific unit (player). Retrieves quest control by difficulty, constructs a quest info packet, and sends to the player client.
// @sourcefile .\QUESTS\QUESTS.CPP
void __fastcall QUEST_SendQuestInfoToUnit(::SGAMEDATA * pGame, D2UnitStrc * pUnit) {
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pUnit);
    D2BitBufferStrc* pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
    GAME::SCmd::NET_D2GS_SERVER_Send_0x28_PlayerQuestInfo(UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\QUESTS\\QUESTS.CPP", 0xca7), 0x28, '\x06', 0, pBitBuffer, 0);
}

void __fastcall QUEST_SetSuccessFinishStates(::SGAMEDATA * pGame, D2QuestGUIDStrc * pQuestGUID, eD2Quests eQuestId, int32_t nSoundId) {
    D2UnitDataPlayerStrc* pPlayerData;
    BOOL bQuestState;
    D2BitBufferStrc* pBitBuffer;
    int nPlayerIdx = 0;
    if (pQuestGUID->nPlayerCount <= 0) {
      return;
    }

    do {
      D2UnitStrc* pUnit;
      pUnit = UNIT::SUnit::FindUnitFromTable(pGame, UNIT_PLAYER, pQuestGUID->aPlayerGUID[nPlayerIdx]);
      if (pUnit) {
        pPlayerData = D2Common::Units::GetPlayerData(pUnit);
        pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
        bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, eQuestId, QUESTSTATE_Completed);
        if (bQuestState != 1) {
          bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, eQuestId, QUESTSTATE_RewardAwaits);
          if (bQuestState != 1) {
            D2Common::QuestRecord::SetQuestState(pBitBuffer, eQuestId, QUESTSTATE_JustCompleted);
            D2Common::QuestRecord::SetQuestState(pBitBuffer, eQuestId, QUESTSTATE_RewardAwaits);
            if (nSoundId) {
              UNIT::SUnit::SetupUpdateEvent_AttachEventSound(pUnit, nSoundId, pUnit);
            }
          }
        }
      }

      nPlayerIdx++;
    } while (nPlayerIdx < (int)(uint32_t)pQuestGUID->nPlayerCount);
}

