// Searches the quest-control timer list for the entry matching both pQuestUpdate (callback) and pQuestData (quest), unlinks it from the singly-linked list, and frees its memory. Asserts the timer list is not currently being executed (bExecuting). Logs a debug message if no matching timer is found.
// @sourcefile .\QUESTS\QUESTS.CPP
void RemoveQuestTimer(D2QuestDataStrc * pQuestData, QUESTUPDATE pQuestUpdate, ::SGAMEDATA * pGame) {
    D2QuestTimerStrc* pMemoryToFree;
    D2QuestControlStrc* pQuestControl = pGame->pQuestControl;
    if (!pQuestControl) {
      return;
    }
    if (pQuestControl->bExecuting) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x42c);
      exit(-1);
    }

    D2QuestTimerStrc* pTimerIter = pQuestControl->pTimer;
    D2QuestTimerStrc* pPrevTimer = 0;
    while (true) {
      pMemoryToFree = pTimerIter;
      if (!pMemoryToFree) {
        break;
      }
      if (pMemoryToFree->pfUpdate == pQuestUpdate && pMemoryToFree->pQuest == pQuestData) {
        if (!pPrevTimer) {
          pQuestControl->pTimer = pMemoryToFree->pNext;
        } else {
          pPrevTimer->pNext = pMemoryToFree->pNext;
        }

        D2_FREE_POOL_AT(pQuestData->pGame->pMemoryPool, pMemoryToFree, ".\\QUESTS\\QUESTS.CPP", 0x43e);
        return;
      }

      pPrevTimer = pMemoryToFree;
      pTimerIter = pMemoryToFree->pNext;
    }

    if (!DEBUGPRINT) {
      return;
    }

    PLAYER::PlayerMsg::PrepareClientMessage(pGame, "Error in timer usage", '\x04');
}

